import type { LunariaUserConfig } from '@lunariajs/core'
import { locales, translatedLocales } from './src/lib/locales.mjs'

export default {
	repository: { name: 'elysiajs/documentation', branch: 'next' },
	sourceLocale: { label: locales.root.label, lang: locales.root.lang },
	locales: translatedLocales.map((lang) => ({
		label: locales[lang].label,
		lang
	})) as LunariaUserConfig['locales'],
	files: [
		{
			include: ['src/content/docs/**/*.{md,mdx}'],
			exclude: [
				`src/content/docs/{${translatedLocales.join(',')}}/**`,
				// generated by starlight-typedoc
				'src/content/docs/reference/**',
				'src/content/docs/design-system.mdx'
			],
			pattern: {
				source: 'src/content/docs/@path',
				locales: 'src/content/docs/@lang/@path'
			},
			type: 'universal'
		}
	]
} satisfies LunariaUserConfig
